CREATE ROLE erp_app LOGIN PASSWORD '...' NOSUPERUSER NOBYPASSRLS;
CREATE ROLE erp_worker LOGIN PASSWORD '...' NOSUPERUSER BYPASSRLS;
CREATE ROLE erp_migrations LOGIN PASSWORD '...' NOSUPERUSER;
GRANT USAGE ON SCHEMA public TO erp_app, erp_worker, erp_migrations;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO erp_app, erp_worker;
GRANT ALL ON SCHEMA public TO erp_migrations;
REVOKE ALL ON SCHEMA public FROM PUBLIC;

roles_base_datos.unidad_trabajo:
class TenantUnitOfWork:
    def __init__(self, tenant_id: UUID):
        self.tenant_id = tenant_id
    async def __aenter__(self) -> AsyncSession:
        self.session = AsyncSessionLocal()
        self.tx = self.session.begin()
        await self.session.execute(text("SELECT set_current_tenant(:t)"), {"t": str(self.tenant_id)})
        return self.session
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        try:
            if exc_type: await self.tx.rollback()
            else: await self.tx.commit()
        finally:
            await self.session.close()

rls_suite.sql:
ALTER TABLE tventas ENABLE ROW LEVEL SECURITY;
ALTER TABLE tventas FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_tventas ON tventas FOR ALL
    USING (papeleria_id = NULLIF(current_setting('app.current_tenant_id', true),'')::uuid)
    WITH CHECK (papeleria_id = NULLIF(current_setting('app.current_tenant_id', true),'')::uuid);

CREATE OR REPLACE FUNCTION set_current_tenant(p UUID) RETURNS void AS $$
BEGIN PERFORM set_config('app.current_tenant_id', p::text, true); END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION generate_uuid_v7() RETURNS uuid AS $$
DECLARE v_time timestamptz := clock_timestamp(); v_secs bigint; v_msec bigint; v_buf bytea;
BEGIN
    v_secs := EXTRACT(EPOCH FROM v_time)::bigint;
    v_msec := (v_secs * 1000) + (EXTRACT(MILLISECONDS FROM v_time)::bigint % 1000);
    v_buf := decode(lpad(to_hex(v_msec), 12, '0') || encode(gen_random_bytes(10), 'hex'), 'hex');
    v_buf := set_byte(v_buf, 6, (get_byte(v_buf, 6) &amp; 15) | 112);
    v_buf := set_byte(v_buf, 8, (get_byte(v_buf, 8) &amp; 63) | 128);
    RETURN encode(v_buf, 'hex')::uuid;
END;
$$ LANGUAGE plpgsql VOLATILE;

