import Dexie, { Table } from 'dexie';
import Decimal from 'decimal.js';
export interface ArticuloLocal { id: string; sku: string; descripcion: string; precio_base: string; stock_actual: string; stock_reservado: string; unidad_medida: string; permite_decimales: boolean; activo: boolean; updated_at: string; }
export interface VentaLocal { client_uuid: string; folio: string; operario_id: string; caja_id: string; sucursal_id: string; estacion_id: string; corte_id?: string; cliente_rel_id?: string; moneda: string; subtotal: string; impuestos: string; descuento_total: string; total: string; metodo_pago: 'efectivo'|'tarjeta'|'transferencia'|'mixto'|'puntos'|'credito'; pagos: Array<{tipo: string; monto: string; referencia?: string}>; origen: 'pos'|'rompefila'; tipo_entrega: 'tienda'|'envio_express'|'pickup'; detalles: any[]; estado: 'pendiente_sync'|'sincronizada'|'conflicto'|'conflicto_corte_cerrado'|'cancelada'; conflicto_motivo?: string; created_at: string; synced_at?: string; trace_id: string; }
export class PosDB extends Dexie {
  articulos!: Table<ArticuloLocal, string>; ventas!: Table<VentaLocal, string>; folios!: Table<any, string>; meta!: Table<{clave: string; valor: string}, string>;
  constructor() { super('PosDB'); this.version(1).stores({ articulos: 'id, sku, descripcion, activo', ventas: 'client_uuid, estado, created_at', folios: 'estacion_id', meta: 'clave' }); }
  async decrementarStockLocal(articulo_id: string, cantidad: Decimal): Promise<void> {
    await this.transaction('rw', this.articulos, async () => {
      const art = await this.articulos.get(articulo_id);
      if (!art) throw new Error(`Artículo ${articulo_id} no existe localmente`);
      await this.articulos.update(articulo_id, { stock_actual: new Decimal(art.stock_actual).minus(cantidad).toString() });
    });
  }
}
export const db = new PosDB();

import { useState, useCallback, useRef } from 'react';
const PALETA = { teclado_numero: '#C9FFE5', teclado_letra: '#F4F9F9', teclado_borrar: '#8FA9B0', teclado_buscar: '#84DCC6', neutro_soft: '#EDF6F7', neutro_deep: '#69A3AC', panel: '#E3EBEE' };
const KB_ABC = [['Q','W','E','R','T','Y','U','I','O','P'], ['A','S','D','F','G','H','J','K','L','Ñ'], ['Z','X','C','V','B','N','M','.','-','@']];
const KB_SYM = [['1','2','3','4','5','6','7','8','9','0'], ['!','"','#','$','%','&amp;','/','(',')','='], ['?','¡','¿','*','+',',',';',':','_','°']];
type KbMode = 'ABC' | 'SYM' | 'NUM';
export function VirtualKeyboard({ onKeyPress, onClose, initialMode = 'ABC' }: { onKeyPress: (key: string) => void; onClose: () => void; initialMode?: KbMode }) {
  const [kbMode, setKbMode] = useState<KbMode>(initialMode);
  const lastPressRef = useRef(0);
  const bindKey = useCallback((action: () => void) => (e: React.PointerEvent) => {
    e.preventDefault(); const now = Date.now(); if (now - lastPressRef.current < 35) return; lastPressRef.current = now; action();
  }, []);
  const makeCharKey = (key: string) => {
    const bg = kbMode === 'SYM' ? PALETA.teclado_numero : PALETA.teclado_letra;
    return <button key={key} onPointerDown={bindKey(() => onKeyPress(key))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm flex-1 text-lg active:scale-95 transition-transform" style={{ background: bg, color: '#0D1B2A' }}>{key}</button>;
  };
  const buildQwerty = () => (<>
    {(kbMode === 'ABC' ? KB_ABC : KB_SYM).map((row, i) => <div key={i} className="flex gap-1 flex-1">{row.map(makeCharKey)}</div>)}
    <div className="flex gap-1 flex-1">
      <button key="TOGGLE" onPointerDown={bindKey(() => setKbMode(kbMode === 'ABC' ? 'SYM' : 'ABC'))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-[10px] flex-[1] active:scale-95" style={{ background: PALETA.neutro_soft, color: PALETA.neutro_deep }}>{kbMode === 'ABC' ? '? 123' : 'Aa ABC'}</button>
      <button key="ESPACIO" onPointerDown={bindKey(() => onKeyPress('ESPACIO'))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-[9px] flex-[4] active:scale-95" style={{ background: PALETA.teclado_letra, color: '#0D1B2A' }}>ESPACIO</button>
      <button key="BORRAR" onPointerDown={bindKey(() => onKeyPress('BORRAR'))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm flex-[1.4] active:scale-95" style={{ background: PALETA.teclado_borrar, color: 'white' }}><i className="fas fa-delete-left" /></button>
      <button key="BUSCAR" onPointerDown={bindKey(() => onKeyPress('BUSCAR'))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-[10px] flex-[1.4] active:scale-95" style={{ background: PALETA.teclado_buscar, color: 'white' }}><i className="fas fa-magnifying-glass mr-1" />BUSCAR</button>
    </div>
  </>);
  const buildNumpad = () => (
    <div className="grid gap-1 h-full" style={{ gridTemplateColumns: 'repeat(4, 1fr)', gridTemplateRows: 'repeat(4, 1fr)' }}>
      {[7,8,9].map(n => <button key={n} onPointerDown={bindKey(() => onKeyPress(String(n)))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-2xl active:scale-95" style={{ background: PALETA.teclado_numero, color: '#0D1B2A' }}>{n}</button>)}
      <button onPointerDown={bindKey(() => onKeyPress('BORRAR'))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm active:scale-95" style={{ background: PALETA.teclado_borrar, color: 'white' }}><i className="fas fa-delete-left" /></button>
      {[4,5,6].map(n => <button key={n} onPointerDown={bindKey(() => onKeyPress(String(n)))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-2xl active:scale-95" style={{ background: PALETA.teclado_numero, color: '#0D1B2A' }}>{n}</button>)}
      <button onPointerDown={bindKey(() => onKeyPress('BUSCAR'))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm active:scale-95" style={{ gridRow: 'span 3', background: PALETA.teclado_buscar, color: 'white' }}><i className="fas fa-magnifying-glass" /></button>
      {[1,2,3].map(n => <button key={n} onPointerDown={bindKey(() => onKeyPress(String(n)))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-2xl active:scale-95" style={{ background: PALETA.teclado_numero, color: '#0D1B2A' }}>{n}</button>)}
      {['00','0','.'].map(k => <button key={k} onPointerDown={bindKey(() => onKeyPress(k))} className="vk-key rounded-lg flex items-center justify-center font-extrabold shadow-sm text-2xl active:scale-95" style={{ background: PALETA.teclado_numero, color: '#0D1B2A' }}>{k}</button>)}
    </div>
  );
  return (
    <div className="fixed inset-0 z-50">
      <div className="absolute inset-0" style={{ background: 'rgba(13,27,42,0.45)' }} onClick={onClose} />
      <div className="absolute bottom-0 left-0 right-0" style={{ background: PALETA.panel, borderTop: '2px solid #8FA9B0' }}>
        <div className="flex items-center justify-between px-3 pt-1.5 pb-1 max-w-[860px] mx-auto">
          <div className="flex items-center gap-1.5">
            <span className="text-[9px] font-bold text-gray-500 uppercase mr-1">Teclado</span>
            {(['ABC', 'SYM', 'NUM'] as KbMode[]).map(mode => <button key={mode} onClick={() => setKbMode(mode)} className="text-[10px] font-bold px-2 py-0.5 rounded transition-colors" style={{ background: kbMode === mode ? '#85E3B3' : '#FFFFFF', color: '#0D1B2A' }}>{mode === 'SYM' ? '123#!' : mode === 'NUM' ? 'NUM' : 'ABC'}</button>)}
          </div>
          <button onClick={onClose} className="text-[10px] font-bold px-2 py-0.5 rounded bg-white border border-gray-300">Cerrar ✕</button>
        </div>
        <div className={`max-w-[860px] mx-auto px-2 py-2 ${kbMode === 'NUM' ? 'grid' : 'flex flex-col gap-1'}`} style={{ height: 195 }}>
          {kbMode === 'NUM' ? buildNumpad() : buildQwerty()}
        </div>
      </div>
    </div>
  );
}

// PaymentModal.tsx — F21: // TODO: useToast() → toast (RG-02/CHK-21)  // F21 - eliminado alert()
import { useState, useMemo, useCallback } from 'react';
import Decimal from 'decimal.js';
import { db, VentaLocal } from '../db/dexieDb';
import { getContextFromJWT, getNextFolio } from '../api/outboxSync';
import { uuidv7 } from 'uuidv7';
import { useToast } from '../components/Toast';  // F21: reemplaza // TODO: useToast()  // F21 - eliminado alert()

export function PaymentModal({ items, total, onClose, onSuccess }: {
  items: any[]; total: string; onClose: () => void; onSuccess: (v: VentaLocal) => void;
}) {
  const { showToast } = useToast();  // F21: hook de toast
  const totalDec = useMemo(() => new Decimal(total), [total]);
  const [pagos, setPagos] = useState<{tipo: string; monto: string}[]>([{ tipo: 'efectivo', monto: total }]);
  const [procesando, setProcesando] = useState(false);
  const totalPagado = useMemo(() => pagos.reduce((sum, p) => sum.add(new Decimal(p.monto)), new Decimal(0)), [pagos]);
  const faltante = useMemo(() => totalDec.minus(totalPagado), [totalDec, totalPagado]);

  const handleCobrar = useCallback(async () => {
    if (faltante.gt(0)) { showToast('Falta cubrir el total', 'error'); return; }  // F21
    setProcesando(true);
    try {
      const ctx = getContextFromJWT();
      const folio = await getNextFolio();
      const client_uuid = uuidv7();
      const subtotal = items.reduce((s, i) => s.add(new Decimal(i.subtotal)), new Decimal(0));
      const impuestos = items.reduce((s, i) => s.add(new Decimal(i.subtotal).mul(new Decimal(i.impuesto_tasa ?? '0.16'))), new Decimal(0));
      const venta: VentaLocal = {
        client_uuid, folio, operario_id: ctx.operario_id, caja_id: ctx.caja_id,
        sucursal_id: ctx.sucursal_id, estacion_id: ctx.estacion_id,
        moneda: 'MXN', subtotal: subtotal.toFixed(2), impuestos: impuestos.toFixed(2),
        descuento_total: '0.00', total: totalDec.toFixed(2),
        metodo_pago: pagos.length === 1 ? (pagos[0].tipo as any) : 'mixto',
        pagos: pagos.map(p => ({ tipo: p.tipo, monto: p.monto })),
        detalles: items.map(i => ({ articulo_id: i.articulo_id, cantidad: i.cantidad,
          precio_unitario: i.precio_unitario, subtotal: i.subtotal, impuesto_id: i.impuesto_id })),
        estado: 'pendiente_sync', created_at: new Date().toISOString(), trace_id: uuidv7(),
      };
      await db.transaction('rw', db.ventas, db.articulos, async () => {
        await db.ventas.add(venta);
        for (const item of items) {
          const art = await db.articulos.get(item.articulo_id);
          if (art) await db.articulos.update(item.articulo_id, {
            stock_actual: new Decimal(art.stock_actual).minus(item.cantidad).toString()
          });
        }
      });
      onSuccess(venta);
    } catch (e: any) {
      showToast(`Error: ${e.message}`, 'error');  // F21: antes // TODO: useToast()  // F21 - eliminado alert()
    } finally { setProcesando(false); }
  }, [faltante, items, pagos, totalDec, onSuccess, showToast]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg shadow-2xl w-full max-w-2xl">
        <div className="px-5 py-3 border-b-2 flex items-center justify-between" style={{ background: 'linear-gradient(90deg, #80FFFF 0%, #B3FBFB 100%)' }}>
          <h2 className="text-lg font-bold">Cobrar venta</h2>
          <button onClick={onClose}><i className="fas fa-times" /></button>
        </div>
        <div className="p-5">
          <div className="flex items-center justify-between mb-4">
            <span className="text-lg font-bold">TOTAL A PAGAR</span>
            <span className="text-3xl font-extrabold" style={{ color: '#0F8A5F' }}>${totalDec.toFixed(2)}</span>
          </div>
          {faltante.gt(0) &amp;&amp; <div className="flex justify-between text-red-500 font-bold mb-2"><span>FALTANTE</span><span>${faltante.toFixed(2)}</span></div>}
          <button onClick={handleCobrar} disabled={faltante.gt(0) || procesando}
            className="w-full py-4 rounded-lg font-extrabold text-lg disabled:opacity-50"
            style={{ background: 'linear-gradient(90deg, #7BFFB9 0%, #A5FFD6 100%)', border: '2px solid #5EE0A8' }}>
            {procesando ? 'Procesando...' : `COBRAR $${totalDec.toFixed(2)}`}
          </button>
        </div>
      </div>
    </div>
  );
}

// pos/src/api/outboxSync.ts — F21: console → logger estructurado dev-only
import axios from 'axios';
import { db, VentaLocal } from '../db/dexieDb';
import { uuidv7 } from 'uuidv7';
import { logger } from '../lib/logger';  // F21: logger estructurado
const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000/api/v1';
export const api = axios.create({ baseURL: API_URL, timeout: 15000, headers: { 'Content-Type': 'application/json' } });
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('pos_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  config.headers['X-Trace-ID'] = uuidv7();
  return config;
});
export async function syncPendingSales() {
  const pending = await db.ventas.where('estado').anyOf('pendiente_sync', 'conflicto', 'conflicto_corte_cerrado').sortBy('created_at');
  if (pending.length === 0) return;
  const batch = pending.slice(0, 50);
  try {
    const { data } = await api.post('/pos/ventas/sync', { ventas: batch });
    for (const res of data.resultados) {
      const nuevoEstado = res.status === 'created' || res.status === 'duplicated' ? 'sincronizada' : (res.status === 'corte_cerrado' ? 'conflicto_corte_cerrado' : 'conflicto');
      await db.ventas.update(res.client_uuid, { estado: nuevoEstado, conflicto_motivo: res.motivo, synced_at: new Date().toISOString() });
    }
    if (pending.length > 50) setTimeout(syncPendingSales, 1000);
  } catch (e: any) {
    logger.error('pos.sync_error', { msg: e.message });  // F21: antes console.error
  }
}
export function initSyncTriggers() {
  window.addEventListener('online', () => {
    logger.debug('pos.online_sync_start');  // F21: antes console.log
    syncPendingSales();
  });
  setInterval(async () => {
    if (navigator.onLine) {
      const count = await db.ventas.where('estado').anyOf('pendiente_sync', 'conflicto', 'conflicto_corte_cerrado').count();
      if (count > 0) await syncPendingSales();
    }
  }, 30000);
}

