# src/api/v1/whatsapp.py from uuid import UUID from fastapi import APIRouter, Depends, HTTPException from sqlalchemy import text from src.infrastructure.db.session import WorkerSessionLocal
async def resolve_tenant_context(db, phone_number_id: str) -> UUID: """F19: resuelve el tenant por el número RECEPTOR y acota la sesión. El webhook corre con erp_worker (BYPASSRLS) → sin este SET, toda escritura es cross-tenant. Regla: papeleria_id explícito en cada INSERT/UPDATE posterior.""" row = (await db.execute(text(""" SELECT papeleria_id FROM papeleria_configuracion WHERE clave = 'whatsapp_phone_number_id' AND valor = :pnid LIMIT 1 """), {"pnid": phone_number_id})).first() if not row: raise HTTPException(404, "Número receptor no mapeado a ningún tenant") await db.execute(text("SELECT set_current_tenant(:t)"), {"t": str(row[0])}) return row[0]
@router.post("/whatsapp/webhook") async def whatsapp_webhook(request: Request): await validar_hmac_meta(request) body = await request.json() # ... parse body ... phone_number_id = extract_phone_number_id(body) async with WorkerSessionLocal() as db: tenant_id = await resolve_tenant_context(db, phone_number_id) # A partir de aquí, TODA escritura lleva papeleria_id=tenant_id explícito await handle_inbound_message(db, tenant_id, body) await db.commit() return {"status": "ok"}

