async def handle_menu(wa_id, msg, ctx, db):
    parts = msg.strip().split()
    if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
        cantidad, idx = int(parts[0]), int(parts[1])
    elif len(parts) == 1 and parts[0].isdigit():
        cantidad, idx = 1, int(parts[0])
    else:
        return await rag_respond(wa_id, msg, ctx, db)   # HÍBRIDO
    articulo = await get_articulo_pagina(db, ctx['pagina'], idx)
    if not articulo:
        return error_item(ctx['lang'])
    await add_item_carrito(db, UUID(ctx['id_carrito']), articulo.id,
                           cantidad, articulo.precio_venta)
    total = await recalcular_total_carrito(db, UUID(ctx['id_carrito']))
    return confirmacion_item(ctx['lang'], articulo.descripcion, cantidad, total)

