import hmac from hashlib import sha256 from pydantic import BaseModel, Field
class SolicitarFacturaRequest(BaseModel): token: str = Field(..., min_length=10) rfc_receptor: str = Field(..., pattern=r"^[A-ZÑ&amp;]{3,4}[0-9]{6}[A-Z0-9]{2}[A0]$") nombre_receptor: str = Field(..., min_length=3, max_length=300) cp_receptor: str = Field(..., pattern=r"^[0-9]{5}$") regimen_fiscal_receptor: str = Field(..., pattern=r"^[0-9]{3}$") uso_cfdi: str = Field(..., pattern=r"^(G01|G02|G03|S01|D01|P01)$")
@router.post("/autofactura/solicitar") async def solicitar_autofactura(payload: SolicitarFacturaRequest, db: AsyncSession = Depends(get_worker_db)): token_hash = sha256(payload.token.encode()).hexdigest() autofactura = (await db.execute(select(TAutofacturaToken).where( TAutofacturaToken.token_hash == token_hash ))).scalar_one_or_none() if not autofactura: raise HTTPException(404, "Token inválido") if autofactura.usado: raise HTTPException(404, "Token ya usado") if autofactura.fecha_expiracion < datetime.now(timezone.utc): raise HTTPException(404, "Token expirado") factura = TFacturaCFDI( papeleria_id=autofactura.papeleria_id, venta_id=autofactura.venta_id, tipo="individual", rfc_receptor=payload.rfc_receptor, nombre_receptor=payload.nombre_receptor, cp_receptor=payload.cp_receptor, regimen_fiscal_receptor=payload.regimen_fiscal_receptor, uso_cfdi=payload.uso_cfdi, estado_cfdi="solicitado", ) db.add(factura) autofactura.usado = True autofactura.usado_en = datetime.now(timezone.utc) await enqueue_event(db, tenant_id=autofactura.papeleria_id, event_type="cfdi.requested", aggregate_type="factura", aggregate_id=str(factura.id), payload={"facturaId": str(factura.id), "tipo": "individual", "ventaId": str(factura.venta_id), "rfcReceptor": payload.rfc_receptor, "nombreReceptor": payload.nombre_receptor, "cpReceptor": payload.cp_receptor, "regimenFiscalReceptor": payload.regimen_fiscal_receptor, "usoCfdi": payload.uso_cfdi}) await db.commit() return {"status": "Factura en cola para timbrado", "factura_id": str(factura.id)}

