# src/application/services/nota_entrega_service.py from fpdf import FPDF import qrcode from io import BytesIO
class NotaEntregaPDF(FPDF): def __init__(self, envio, venta, cliente): super().__init__(format='LETTER') self.envio = envio self.venta = venta self.cliente = cliente
def header(self): self.set_font('Helvetica', 'B', 14) self.cell(0, 10, 'NOTA DE ENTREGA — PapelMind', ln=1, align='C') self.set_font('Helvetica', '', 9) self.cell(0, 6, f'Folio: {self.venta.folio}', ln=1) self.cell(0, 6, f'Fecha: {self.envio.created_at.strftime("%d/%m/%Y %H:%M")}', ln=1) self.ln(4)
def body(self): self.set_font('Helvetica', 'B', 11) self.cell(0, 8, 'ENTREGAR A:', ln=1) self.set_font('Helvetica', '', 10) self.multi_cell(0, 5, f'{self.cliente.display_name}\n' f'{self.envio.direccion.calle_numero}\n' f'Col. {self.envio.direccion.colonia}\n' f'CP {self.envio.direccion.codigo_postal}\n' f'Ref: {self.envio.direccion.referencias or "N/A"}') self.ln(6) self.set_font('Helvetica', 'B', 11) self.cell(0, 8, 'PRODUCTOS:', ln=1) self.set_font('Helvetica', '', 10) for item in self.venta.detalles: self.cell(0, 6, f'• {item.cantidad} x {item.articulo.descripcion}', ln=1) self.ln(6) # QR tracking qr = qrcode.make(f'https://dispatch.papelmind.com/tracking/{self.envio.qr_token}') buf = BytesIO() qr.save(buf, format='PNG') self.image(buf, x=150, y=100, w=40) # Firma self.set_y(-40) self.set_font('Helvetica', '', 9) self.cell(80, 6, '_____', ln=0) self.cell(80, 6, '_____', ln=1) self.cell(80, 6, 'Firma recibido', ln=0) self.cell(80, 6, 'Nombre y fecha', ln=1)
def generar(self) -> bytes: self.add_page() self.header() self.body() return bytes(self.output())

