# src/infrastructure/workers/notification_worker.py
import asyncio, json, httpx
from aiokafka import AIOKafkaConsumer
from src.core.config import settings
import structlog

logger = structlog.get_logger(__name__)

class NotificationWorker:
    def __init__(self):
        self.wa_endpoint = f"https://graph.facebook.com/v18.0/{settings.WHATSAPP_PHONE_NUMBER_ID}/messages"

    async def _enviar_whatsapp(self, numero: str, payload: dict) -> dict:
        headers = {"Authorization": f"Bearer {settings.WHATSAPP_ACCESS_TOKEN}"}
        body = {"messaging_product": "whatsapp",
                "to": numero.replace("+","").replace(" ","").replace("-","")}
        if payload.get("tipoContenido") == "template":
            body["type"] = "template"
            body["template"] = {"name": payload["plantilla"]["nombre"],
                                "language": {"code": payload["plantilla"].get("idioma","es_MX")}}
        elif payload.get("tipoContenido") == "interactive":
            body["type"] = "interactive"; body["interactive"] = payload["interactivo"]
        else:
            body["type"] = "text"; body["text"] = {"body": payload.get("texto","")[:4096]}
        delays = [1, 5, 15]
        async with httpx.AsyncClient(timeout=15.0) as client:
            for i in range(3):
                try:
                    r = await client.post(self.wa_endpoint, json=body, headers=headers)
                    if r.status_code == 200:
                        return {"ok": True, "mensajeExternoId": r.json().get("messages",[{}])[0].get("id")}
                except Exception as e:
                    logger.warning(f"notification_worker.intento_{i+1}_fallo", error=str(e)[:200])
                if i < 2: await asyncio.sleep(delays[i])
        return {"ok": False}

    async def run(self):
        consumer = AIOKafkaConsumer("notifications.whatsapp.send", "notifications.email.send",
            bootstrap_servers=settings.KAFKA_BOOTSTRAP_SERVERS, group_id="notification_group")
        await consumer.start()
        try:
            async for msg in consumer:
                event = json.loads(msg.value.decode())
                payload = event["payload"]
                if msg.topic == "notifications.whatsapp.send":
                    res = await self._enviar_whatsapp(payload["numeroDestino"], payload)
                    logger.info(f"[WA] {event['eventType']} → {payload['numeroDestino']}: {res}")
        finally:
            await consumer.stop()

if __name__ == "__main__":
    asyncio.run(NotificationWorker().run())

# src/infrastructure/workers/dlq_consumer.py import asyncio, json from datetime import datetime, timezone from aiokafka import AIOKafkaConsumer from sqlalchemy import text from src.infrastructure.db.session import WorkerSessionLocal from src.core.config import settings
async def consume_dlq(): """Persiste eventos DLQ en tdlq_eventos (retención 90d vs 30d del topic crudo). FIX F9: historial_intentos JSONB con trazabilidad por intento. FIX F26: usa settings.KAFKA_BOOTSTRAP_SERVERS (no hardcodea kafka:9092).""" consumer = AIOKafkaConsumer("dlq.events", bootstrap_servers=settings.KAFKA_BOOTSTRAP_SERVERS, group_id="dlq_group") await consumer.start() try: async for msg in consumer: ev = json.loads(msg.value.decode()) async with WorkerSessionLocal() as session: await session.execute(text(""" INSERT INTO tdlq_eventos (id, outbox_evento_id, papeleria_id, event_type, aggregate_type, aggregate_id, payload, error_ultimo, historial_intentos, trace_id, estado, first_failed_at) VALUES (generate_uuid_v7(), :oeid, :tid, :etipo, :agg, :aggid, CAST(:payload AS jsonb), :err, CAST(:hist AS jsonb), :trace, 'pendiente', NOW()) ON CONFLICT (outbox_evento_id) DO UPDATE SET error_ultimo = EXCLUDED.error_ultimo, historial_intentos = tdlq_eventos.historial_intentos || CAST(:nuevo_intento AS jsonb) """), { "oeid": ev.get("eventId"), "tid": ev.get("tenantId"), "etipo": ev.get("eventType"), "agg": ev.get("aggregate_type"), "aggid": ev.get("aggregate_id"), "payload": json.dumps(ev.get("payload", {})), "err": ev.get("error"), "trace": ev.get("traceId"), "hist": json.dumps([{"intento": ev.get("intentos"), "error": ev.get("error"), "timestamp": datetime.now(timezone.utc).isoformat()}]), "nuevo_intento": json.dumps({"intento": ev.get("intentos"), "error": ev.get("error"), "timestamp": datetime.now(timezone.utc).isoformat()})}) await session.commit() finally: await consumer.stop()
if __name__ == "__main__": asyncio.run(consume_dlq())

